package com.newzkl.platform.base.biz.order.model.req;import lombok.Data;import java.time.LocalDateTime;/** * 订单状态记录新增请求对象 * * @author sijiwang * @since 2026-01-30 */@Datapublic class OrderStateRecordCreateReq {    /**     * 订单主键ID（关联订单表）     */    private Long orderId;    /**     * SPU订单ID（关联SPU订单表）     */    private Long spuOrderId;    /**     * SKU订单ID（关联SKU订单表）     */    private Long skuOrderId;    /**     * 变更前订单状态     */    private Integer beforeOrderState;    /**     * 变更前订单状态描述     */    private String beforeStateDesc;    /**     * 变更后订单状态     */    private Integer afterOrderState;    /**     * 变更后订单状态描述     */    private String afterStateDesc;    /**     * 下单人ID（关联用户表，匿名订单可为null）     */    private Long ordererId;    /**     * 操作人ID（关联用户表；系统自动操作时为null）     */    private Long operatorId;    /**     * 操作人角色ID     */    private Long operatorRoleId;    /**     * 角色描述     */    private String roleDesc;    /**     * 操作时间（订单状态变更的实际时间）     */    private LocalDateTime operateTime;    /**     * 拓展字段（JSON格式）     */    private String ext;}